create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, email text, created_at timestamptz default now());
alter table profiles add column if not exists employee_code text unique;
alter table profiles add column if not exists phone text;
alter table profiles add column if not exists position text;
alter table profiles add column if not exists must_change_password boolean not null default false;
alter table profiles add column if not exists profile_completed boolean not null default true;
alter table profiles add column if not exists updated_at timestamptz not null default now();
create table if not exists roles(id uuid primary key default gen_random_uuid(), name text unique not null, description text, created_at timestamptz default now());
create table if not exists permissions(id uuid primary key default gen_random_uuid(), code text unique not null, description text);
create table if not exists user_roles(user_id uuid references profiles(id) on delete cascade, role_id uuid references roles(id) on delete cascade, primary key(user_id,role_id));
create table if not exists role_permissions(role_id uuid references roles(id) on delete cascade, permission_id uuid references permissions(id) on delete cascade, primary key(role_id,permission_id));
create table if not exists meta_ad_accounts(id text primary key, name text not null, currency text default 'VND', timezone_name text, active boolean default true, synced_at timestamptz);
create table if not exists meta_campaigns(id text primary key, ad_account_id text references meta_ad_accounts(id) on delete cascade, name text not null, status text, objective text, synced_at timestamptz);
create table if not exists meta_adsets(id text primary key, campaign_id text references meta_campaigns(id) on delete cascade, name text not null, status text, synced_at timestamptz);
create table if not exists meta_ads(id text primary key, adset_id text references meta_adsets(id) on delete cascade, name text not null, status text, synced_at timestamptz);
create table if not exists ad_daily_metrics(id bigint generated always as identity primary key, metric_date date not null, ad_account_id text references meta_ad_accounts(id), campaign_id text references meta_campaigns(id), adset_id text references meta_adsets(id), ad_id text references meta_ads(id), spend numeric default 0, impressions bigint default 0, reach bigint default 0, frequency numeric default 0, clicks bigint default 0, ctr numeric default 0, cpc numeric default 0, cpm numeric default 0, messages bigint default 0, leads bigint default 0, qualified_leads bigint default 0, synced_at timestamptz default now(), unique(metric_date,ad_account_id,campaign_id,adset_id,ad_id));
create table if not exists marketing_plans(id uuid primary key default gen_random_uuid(), name text not null, starts_on date, ends_on date, budget numeric default 0, target_messages int, target_leads int, target_qualified_leads int, target_cpl numeric, created_by uuid references profiles(id), created_at timestamptz default now());
create table if not exists marketing_plan_entities(id uuid primary key default gen_random_uuid(), plan_id uuid references marketing_plans(id) on delete cascade, entity_type text check(entity_type in ('campaign','adset','ad')), entity_id text not null);
create table if not exists conversations(id text primary key, page_id text, sender_psid text, first_message_at timestamptz, last_message_at timestamptz, campaign_id text, adset_id text, ad_id text, phone text, crm_status text, synced_at timestamptz);
create table if not exists crm_channel_daily_metrics(id bigint generated always as identity primary key, metric_date date not null, source text not null check(source in ('Tiktok','Youtube','Website')), messages bigint not null default 0 check(messages >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(metric_date,source));
alter table crm_channel_daily_metrics enable row level security;
create table if not exists conversation_tags(id uuid primary key default gen_random_uuid(), conversation_id text references conversations(id) on delete cascade, meta_tag_id text, meta_tag_name text, created_at timestamptz default now());
create table if not exists customers(id uuid primary key default gen_random_uuid(), full_name text, phone text unique, created_at timestamptz default now());
create table if not exists customer_sources(id uuid primary key default gen_random_uuid(), customer_id uuid references customers(id) on delete cascade, platform text default 'meta', campaign_id text, adset_id text, ad_id text, conversation_id text, first_touch_at timestamptz);
create table if not exists crm_leads(id uuid primary key default gen_random_uuid(), created_at timestamptz default now(), customer_id uuid references customers(id) on delete set null, account_name text not null check(btrim(account_name) <> ''), source text not null check(source in ('Tiktok','Website','Fanpage','Youtube')), real_name text, phone text, has_zalo boolean not null default false, address text, account_link text, status text not null default 'Đang tiếp nhận' check(status in ('Đang tiếp nhận','Gửi báo giá','Lên showroom','Tư vấn tại nhà','Chốt hợp đồng','Giới thiệu khách mới','Sổ quét','Đi khảo sát','Chưa nghe máy')), quality text not null default 'Đang đánh giá' check(quality in ('Đang đánh giá','Đạt chất lượng','Không phù hợp')), description text, created_by uuid references profiles(id), check(nullif(btrim(phone),'') is not null or has_zalo));
alter table crm_leads add column if not exists segment text;
alter table crm_leads add column if not exists scene_code text;
alter table crm_leads add column if not exists quote_value numeric check (quote_value >= 0);
alter table crm_leads add column if not exists ended_at timestamptz;
alter table crm_leads add column if not exists end_reason text;
alter table crm_leads drop constraint if exists crm_leads_source_check;
alter table crm_leads add constraint crm_leads_source_check check(source in ('Tiktok','Website','Fanpage','Youtube','Khách tự đến showroom'));
create table if not exists crm_checklist_items(id uuid primary key default gen_random_uuid(), group_key text not null check(group_key in ('segments','scene_codes','lead_statuses','lead_quality')), label text not null, value text, is_active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(group_key,label));
alter table crm_checklist_items drop constraint if exists crm_checklist_items_group_key_check;
alter table crm_checklist_items add constraint crm_checklist_items_group_key_check check(group_key in ('segments','scene_codes','lead_statuses','lead_quality','job_positions','work_branches'));
create table if not exists marketing_team_tasks(id uuid primary key default gen_random_uuid(),branch text not null,title text not null,description text,assigned_to uuid references profiles(id) on delete set null,status text not null default 'Đang thực hiện' check(status in ('Chưa bắt đầu','Đang thực hiện','Tạm dừng','Hoàn thành')),starts_on date,due_on date,created_by uuid references profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table marketing_team_tasks enable row level security;
grant select,insert,update,delete on table marketing_team_tasks to service_role;
create table if not exists media_projects(id uuid primary key default gen_random_uuid(),project_name text not null check(nullif(btrim(project_name),'') is not null),customer_name text,address text not null check(nullif(btrim(address),'') is not null),contact_phone text,notes text,created_by uuid references profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table media_projects alter column address drop not null;
alter table media_projects drop constraint if exists media_projects_address_check;
alter table media_projects add column if not exists map_url text;
alter table media_projects add column if not exists scheduled_at timestamptz;
alter table media_projects add column if not exists status text not null default 'active';
alter table media_projects add column if not exists cancellation_reason text;
alter table media_projects add column if not exists cancelled_at timestamptz;
alter table media_projects drop constraint if exists media_projects_status_check;
alter table media_projects add constraint media_projects_status_check check(status in ('active','cancelled'));
alter table media_projects drop constraint if exists media_projects_cancel_reason_check;
alter table media_projects add constraint media_projects_cancel_reason_check check(status<>'cancelled' or nullif(btrim(cancellation_reason),'') is not null);
create index if not exists media_projects_status_schedule_idx on media_projects(status,scheduled_at);
create table if not exists media_project_stages(id uuid primary key default gen_random_uuid(),project_id uuid not null references media_projects(id) on delete cascade,stage text not null check(stage in ('survey','installation','handover','homeowner_interview')),status text not null default 'pending' check(status in ('pending','scheduled','completed','cancelled')),scheduled_at timestamptz,assigned_to uuid references profiles(id) on delete set null,shot_list text,notes text,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(project_id,stage));
alter table media_project_stages add column if not exists workflow_status text not null default 'waiting' check(workflow_status in ('waiting','filmed','editing','ready','published'));
alter table media_project_stages add column if not exists published_url text;
alter table media_project_stages add column if not exists published_at timestamptz;
alter table media_project_stages drop constraint if exists media_project_stages_stage_check;
alter table media_project_stages add constraint media_project_stages_stage_check check(stage in ('survey','installation','handover','homeowner_interview'));
create index if not exists media_project_stages_schedule_idx on media_project_stages(scheduled_at,status) where status in ('pending','scheduled');
create index if not exists media_project_stages_project_idx on media_project_stages(project_id,stage);
alter table media_projects enable row level security;
alter table media_project_stages enable row level security;
revoke all on table media_projects,media_project_stages from anon,authenticated;
grant select,insert,update,delete on table media_projects,media_project_stages to service_role;
create table if not exists ad_sync_logs(id bigint generated always as identity primary key, sync_type text, status text, detail jsonb, started_at timestamptz default now(), finished_at timestamptz);
create table if not exists content_items(id uuid primary key default gen_random_uuid(),platform text not null check(platform in ('tiktok','fanpage','youtube','website')),content_type text not null default 'post' check(content_type in ('post','video','article','short','reel')),title text not null check(nullif(btrim(title),'') is not null),content_url text,external_id text,published_at timestamptz not null,status text not null default 'published' check(status in ('draft','published','archived')),created_by uuid references profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(platform,external_id));
create table if not exists content_metric_snapshots(id bigint generated always as identity primary key,content_id uuid not null references content_items(id) on delete cascade,metric_date date not null default current_date,views bigint not null default 0 check(views>=0),reach bigint not null default 0 check(reach>=0),impressions bigint not null default 0 check(impressions>=0),likes bigint not null default 0 check(likes>=0),comments bigint not null default 0 check(comments>=0),shares bigint not null default 0 check(shares>=0),saves bigint not null default 0 check(saves>=0),clicks bigint not null default 0 check(clicks>=0),leads bigint not null default 0 check(leads>=0),watch_time_seconds bigint not null default 0 check(watch_time_seconds>=0),source text not null default 'manual' check(source in ('manual','api')),synced_at timestamptz not null default now(),unique(content_id,metric_date));
create table if not exists content_kpi_targets(id uuid primary key default gen_random_uuid(),month date not null check(month=date_trunc('month',month)::date),platform text not null check(platform in ('tiktok','fanpage','youtube','website')),posts_target int not null default 0 check(posts_target>=0),views_target bigint not null default 0 check(views_target>=0),engagement_rate_target numeric(8,4) not null default 0 check(engagement_rate_target>=0),leads_target int not null default 0 check(leads_target>=0),created_by uuid references profiles(id) on delete set null,updated_at timestamptz not null default now(),unique(month,platform));
create index if not exists content_items_platform_published_idx on content_items(platform,published_at desc);
create index if not exists content_metric_snapshots_content_date_idx on content_metric_snapshots(content_id,metric_date desc);
create index if not exists content_kpi_targets_month_idx on content_kpi_targets(month,platform);
alter table content_items enable row level security;
alter table content_metric_snapshots enable row level security;
alter table content_kpi_targets enable row level security;
revoke all on table content_items,content_metric_snapshots,content_kpi_targets from anon,authenticated;
grant select,insert,update,delete on table content_items,content_metric_snapshots,content_kpi_targets to service_role;
grant usage,select on sequence content_metric_snapshots_id_seq to service_role;
create table if not exists integration_connections(id uuid primary key default gen_random_uuid(),provider text not null check(provider in ('tiktok','meta')),external_account_id text not null,display_name text,access_token_encrypted text not null,refresh_token_encrypted text,access_token_expires_at timestamptz not null,refresh_token_expires_at timestamptz,scopes text[] not null default '{}',status text not null default 'active' check(status in ('active','expired','revoked','error')),connected_by uuid references profiles(id) on delete set null,connected_at timestamptz not null default now(),updated_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb,unique(provider,external_account_id));
create index if not exists integration_connections_provider_status_idx on integration_connections(provider,status);
alter table integration_connections enable row level security;
revoke all on table integration_connections from anon,authenticated;
grant select,insert,update,delete on table integration_connections to service_role;
create table if not exists daily_manual_reports(id uuid primary key default gen_random_uuid(),report_date date not null unique,content text,amount numeric(14,0) check(amount>=0),messages bigint check(messages>=0),created_by uuid references profiles(id) on delete set null,updated_by uuid references profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table daily_manual_reports add column if not exists amount numeric(14,0) check(amount>=0);
alter table daily_manual_reports add column if not exists messages bigint check(messages>=0);
alter table daily_manual_reports alter column content drop not null;
alter table daily_manual_reports drop constraint if exists daily_manual_reports_content_check;
create index if not exists daily_manual_reports_date_idx on daily_manual_reports(report_date desc);
alter table daily_manual_reports enable row level security;
revoke all on table daily_manual_reports from anon,authenticated;
grant select,insert,update,delete on table daily_manual_reports to service_role;
insert into roles(name) values ('Giám đốc'),('Trưởng phòng Marketing'),('Nhân viên Media'),('Nhân viên Marketing tổng hợp'),('Kế toán'),('Sale Admin') on conflict do nothing;
insert into permissions(code) values ('users.manage'),('roles.manage'),('ads.view'),('ads.manage'),('budget.manage'),('leads.view'),('leads.manage'),('reports.view'),('finance.view') on conflict do nothing;
